/**
 * Passphrase normalization.
 *
 * The same visible passphrase can be different bytes on two devices: a
 * precomposed e-acute or e plus a combining accent, or full-width characters
 * from a Japanese input method. Writers therefore use NFKC(passphrase) for the
 * key and for `passphrase_hash`, and readers try NFKC, the string as typed,
 * NFC and NFD and keep the form whose key authenticates.
 *
 * `fixtures/passphraseNormalizationVectors.json` is a byte-for-byte copy of
 * `src/lib/__tests__/fixtures/passphraseNormalizationVectors.json` in the
 * LinkPilot web app. It was generated by an implementation that shares no code
 * with any client. As with the other fixture: do not "fix" a failure here by
 * regenerating it.
 *
 * Every non-ASCII string in this file is written with \u escapes, so composed
 * and decomposed forms survive editors and git.
 */

import { describe, it, expect, vi } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { createHash } from "node:crypto";
import {
  decryptPayload,
  encryptPayload,
  normalizePassphrase,
  passphraseCandidates,
  resolveContentKey,
  toBase64Url,
  PBKDF2_ITERATIONS,
  HKDF_INFO,
} from "../src/crypto.js";
import { LinkPilot, API_KEY_PREFIX } from "../src/index.js";

const SLOW = 60_000;

interface Vector {
  name: string;
  kind: "normalized" | "legacy";
  plaintext: string;
  stored: string;
  fragmentKey: string;
  contentKey: string;
  passphraseHash: string;
  accepted: string[];
  rejected: string[];
}

const here = dirname(fileURLToPath(import.meta.url));
const fixture = JSON.parse(
  readFileSync(resolve(here, "fixtures/passphraseNormalizationVectors.json"), "utf8"),
) as {
  format: string;
  writerNormalization: string;
  readerCandidates: string[];
  pbkdf2Iterations: number;
  hkdfInfo: string;
  vectors: Vector[];
};
const vectors = fixture.vectors;

const KEY = `${API_KEY_PREFIX}0123456789abcdef0123456789abcdef`;

/** What the SDK puts on the wire for `secrets.create` with this passphrase. */
async function createAndCapture(
  secret: string,
  passphrase: string,
): Promise<{ ciphertext: string; passphrase_hash: string; fragmentKey: string; rawBody: string }> {
  let rawBody = "";
  const fetchStub = (async (_input: string | URL, init?: RequestInit) => {
    rawBody = String(init?.body);
    return new Response(
      JSON.stringify({ id: "s", secret_url: "https://shrd.link/s/aaaaaaaaaa", expires_at: null, burn_after_read: true }),
      { status: 201, headers: { "Content-Type": "application/json" } },
    );
  }) as unknown as typeof globalThis.fetch;
  const out = await new LinkPilot({ apiKey: KEY, fetch: fetchStub }).secrets.create({ secret, passphrase });
  const body = JSON.parse(rawBody) as { ciphertext: string; passphrase_hash: string };
  return { ...body, fragmentKey: out.fragmentKey, rawBody };
}

/** SHA-256 hex from Node's own hash, not the WebCrypto path the SDK uses. */
function sha256Hex(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

function pbkdf2Calls(spy: { mock: { calls: unknown[][] } }): number {
  return spy.mock.calls.filter((c) => (c[0] as { name?: string }).name === "PBKDF2").length;
}

describe("passphrase forms", () => {
  it("normalizes to NFKC", () => {
    expect(normalizePassphrase("cafe\u0301")).toBe("caf\u00e9");
    expect(normalizePassphrase("\uff50\uff41\uff53\uff53\uff11\uff12\uff13")).toBe("pass123");
    expect(normalizePassphrase("\ufb01le")).toBe("file");
  });

  it("never trims or changes case", () => {
    expect(normalizePassphrase(" Pass ")).toBe(" Pass ");
    expect(normalizePassphrase("\tTab and newline\n")).toBe("\tTab and newline\n");
  });

  it("gives an ASCII passphrase exactly one candidate, itself", () => {
    for (const p of ["hunter2", "correct horse battery staple", " leading and trailing ", "Tr0ub4dor&3", ""]) {
      expect(passphraseCandidates(p)).toEqual([p]);
    }
  });

  it("lists NFKC first, then as typed, then NFC and NFD, without duplicates", () => {
    const typed = "\uff50cafe\u0301"; // full-width p + decomposed e-acute
    expect(passphraseCandidates(typed)).toEqual([
      "pcaf\u00e9", // NFKC
      typed, // as typed
      "\uff50caf\u00e9", // NFC
      // NFD equals the string as typed, so it is not listed twice
    ]);
    // All four forms differ: full-width p, a composed and a decomposed accent.
    const four = "\uff50caf\u00e9 cafe\u0301";
    expect(passphraseCandidates(four)).toEqual([
      "pcaf\u00e9 caf\u00e9",
      four,
      "\uff50caf\u00e9 caf\u00e9",
      "\uff50cafe\u0301 cafe\u0301",
    ]);
  });
});

describe("known-answer vectors shared with the web app", () => {
  it("pins the same cost parameters and has both kinds of vector", () => {
    expect(fixture.format).toBe("v1p");
    expect(fixture.writerNormalization).toBe("NFKC");
    expect(fixture.readerCandidates).toEqual(["NFKC", "as typed", "NFC", "NFD"]);
    expect(PBKDF2_ITERATIONS).toBe(fixture.pbkdf2Iterations);
    expect(HKDF_INFO).toBe(fixture.hkdfInfo);
    expect(vectors.length).toBe(10);
    expect(vectors.filter((v) => v.kind === "normalized").length).toBeGreaterThanOrEqual(6);
    expect(vectors.filter((v) => v.kind === "legacy").length).toBeGreaterThanOrEqual(3);
    for (const v of vectors) {
      expect(v.stored.startsWith("v1p.")).toBe(true);
      expect(v.accepted.length).toBeGreaterThanOrEqual(1);
      expect(v.rejected.length).toBeGreaterThanOrEqual(1);
    }
  });

  for (const v of vectors) {
    describe(v.name, () => {
      it(
        "every accepted form decrypts it and resolves the writer's content key",
        async () => {
          for (const typed of v.accepted) {
            expect(await decryptPayload(v.stored, v.fragmentKey, typed)).toBe(v.plaintext);
            // The attachment key is derived from this, so it must be the
            // writer's key whichever form the reader typed.
            expect(toBase64Url(await resolveContentKey(v.stored, v.fragmentKey, typed))).toBe(v.contentKey);
          }
        },
        SLOW,
      );

      it(
        "every rejected form fails with decrypt_failed",
        async () => {
          for (const typed of v.rejected) {
            await expect(decryptPayload(v.stored, v.fragmentKey, typed)).rejects.toMatchObject({
              code: "decrypt_failed",
            });
            expect(toBase64Url(await resolveContentKey(v.stored, v.fragmentKey, typed))).not.toBe(v.contentKey);
          }
        },
        SLOW,
      );
    });
  }

  it(
    "a normalized vector's stored hash is the passphrase_hash the SDK sends for any accepted form",
    async () => {
      for (const v of vectors.filter((x) => x.kind === "normalized")) {
        for (const typed of v.accepted) {
          const sent = await createAndCapture("x", typed);
          expect(sent.passphrase_hash).toBe(v.passphraseHash);
        }
      }
    },
    SLOW,
  );

  it("a legacy vector's stored hash is the hash of the passphrase as its writer typed it", () => {
    // Nothing in the SDK produces these any more. This pins what the fixture
    // means, so a reader that hashes for itself knows why the NFKC hash can
    // miss on a secret written before normalization.
    for (const v of vectors.filter((x) => x.kind === "legacy")) {
      expect(v.accepted.map(sha256Hex)).toContain(v.passphraseHash);
    }
  });
});

describe("what the SDK writes", () => {
  it(
    "derives the key and the hash from the NFKC form, and sends neither form of the passphrase",
    async () => {
      const typed = "\uff50cafe\u0301"; // full-width p + decomposed e-acute
      const sent = await createAndCapture("vpn.conf", typed);
      expect(sent.passphrase_hash).toBe(sha256Hex("pcaf\u00e9"));
      expect(sent.passphrase_hash).not.toBe(sha256Hex(typed));
      expect(sent.rawBody).not.toContain(typed);
      expect(sent.rawBody).not.toContain("pcaf\u00e9");
      expect(sent.ciphertext.startsWith("v1p.")).toBe(true);
      // Any reader form opens it, to the same key.
      for (const reader of [typed, "pcaf\u00e9", "pcafe\u0301", "\uff50caf\u00e9"]) {
        expect(await decryptPayload(sent.ciphertext, sent.fragmentKey, reader)).toBe("vpn.conf");
      }
      await expect(decryptPayload(sent.ciphertext, sent.fragmentKey, "pcafe")).rejects.toMatchObject({
        code: "decrypt_failed",
      });
    },
    SLOW,
  );

  it("sends the same hash as before for an ASCII passphrase", async () => {
    for (const p of ["open sesame", " Open Sesame ", "Tr0ub4dor&3"]) {
      expect((await createAndCapture("x", p)).passphrase_hash).toBe(sha256Hex(p));
    }
  });
});

describe("round trips across forms", () => {
  const pairs: Array<[string, string, string]> = [
    ["decomposed writer, composed reader", "cafe\u0301-Mu\u0308ller", "caf\u00e9-M\u00fcller"],
    ["composed writer, decomposed reader", "caf\u00e9", "cafe\u0301"],
    [
      "full-width writer, half-width reader",
      "\uff50\uff41\uff53\uff53\uff57\uff4f\uff52\uff44\uff11",
      "password1",
    ],
    [
      "half-width writer, full-width reader",
      "password1",
      "\uff50\uff41\uff53\uff53\uff57\uff4f\uff52\uff44\uff11",
    ],
    [
      "full-width katakana writer, half-width katakana reader",
      "\u30d1\u30b9\u30ef\u30fc\u30c9",
      "\uff8a\uff9f\uff7d\uff9c\uff70\uff84\uff9e",
    ],
  ];

  for (const [label, written, typed] of pairs) {
    it(
      label,
      async () => {
        const { stored, fragmentKey } = await encryptPayload(`payload-${label}`, written);
        expect(await decryptPayload(stored, fragmentKey, typed)).toBe(`payload-${label}`);
        expect(await decryptPayload(stored, fragmentKey, written)).toBe(`payload-${label}`);
        expect(toBase64Url(await resolveContentKey(stored, fragmentKey, typed))).toBe(
          toBase64Url(await resolveContentKey(stored, fragmentKey, written)),
        );
      },
      SLOW,
    );
  }
});

describe("cost for an ASCII passphrase is unchanged", () => {
  it(
    "one PBKDF2 derivation to decrypt, right or wrong",
    async () => {
      const { stored, fragmentKey } = await encryptPayload("x", "hunter2");
      const spy = vi.spyOn(globalThis.crypto.subtle, "deriveBits");
      try {
        expect(await decryptPayload(stored, fragmentKey, "hunter2")).toBe("x");
        expect(pbkdf2Calls(spy)).toBe(1);
        spy.mockClear();
        await expect(decryptPayload(stored, fragmentKey, "hunter3")).rejects.toMatchObject({
          code: "decrypt_failed",
        });
        expect(pbkdf2Calls(spy)).toBe(1);
      } finally {
        spy.mockRestore();
      }
    },
    SLOW,
  );

  it(
    "one PBKDF2 derivation to encrypt",
    async () => {
      const spy = vi.spyOn(globalThis.crypto.subtle, "deriveBits");
      try {
        await encryptPayload("x", "caf\u00e9");
        expect(pbkdf2Calls(spy)).toBe(1);
      } finally {
        spy.mockRestore();
      }
    },
    SLOW,
  );

  it(
    "at most four derivations for a wrong non-ASCII passphrase",
    async () => {
      const { stored, fragmentKey } = await encryptPayload("x", "caf\u00e9");
      const spy = vi.spyOn(globalThis.crypto.subtle, "deriveBits");
      try {
        await expect(decryptPayload(stored, fragmentKey, "\uff50cafe\u0301")).rejects.toMatchObject({
          code: "decrypt_failed",
        });
        expect(pbkdf2Calls(spy)).toBeGreaterThan(1);
        expect(pbkdf2Calls(spy)).toBeLessThanOrEqual(4);
      } finally {
        spy.mockRestore();
      }
    },
    SLOW,
  );
});
